const storage = new Map();

const localStorage = {
  setItem(key, value) {
    storage.set(key, String(value));
  },
  getItem(key) {
    return storage.get(key) || null;
  },
  removeItem(key) {
    storage.delete(key);
  },
  clear() {
    storage.clear();
  },
  get length() {
    return storage.size;
  }
};

localStorage.setItem('name', 'Alice');
localStorage.setItem('theme', 'dark');
localStorage.setItem('score', '95');

console.log('Items:', localStorage.length);
console.log('Name:', localStorage.getItem('name'));
console.log('Theme:', localStorage.getItem('theme'));
console.log('Score:', localStorage.getItem('score'));

localStorage.removeItem('score');
console.log('After remove:', localStorage.length);

localStorage.clear();
console.log('After clear:', localStorage.length);
console.log('Name after clear:', localStorage.getItem('name'));
